// Validate Document Composer output
const input = $input.first().json;
let output = input.output || input.response || input.text || input.content || '';

let parsed;
try {
  const mdMatch = output.match(/```json\n([\s\S]*?)\n```/) || output.match(/```\n([\s\S]*?)\n```/);
  if (mdMatch && mdMatch[1]) parsed = JSON.parse(mdMatch[1].trim());
  else {
    const jsonMatch = output.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    else parsed = JSON.parse(output);
  }
} catch (e) {
  return [{
    json: {
      valid: false,
      error: 'Parse error: ' + e.message,
      raw_output: output.substring(0, 3000),
      section_name: input.section_name || 'Unknown',
      content: output,
      key_points: [],
      completeness: 'partial'
    }
  }];
}

if (!parsed.section_name) parsed.section_name = input.section_name || 'Unknown';
if (!parsed.content) parsed.content = 'Error: no content generated';
if (!Array.isArray(parsed.key_points)) parsed.key_points = [];
if (!parsed.completeness) parsed.completeness = 'partial';

return [{ json: { valid: true, ...parsed } }];
